pub(super) async fn run_dependencies(
    &self,
    company: CompanyId,
    run: RunId,
) -> AppResult<RunDependencies> {
    tokio::time::timeout(Duration::from_secs(5), async {
        let ownership: OwnershipRow = sqlx::query_as(
            "SELECT manifest_id, root_run_id FROM run_dependency_manifests WHERE company_id=$1 AND run_id=$2"
        ).bind(company.as_uuid()).bind(run.as_uuid()).fetch_optional(self.pool()).await?
            .ok_or_else(invalid_provenance)?;
        let sql = format!("{REVISIONS} ORDER BY selection.agent_id LIMIT $4");
        let mut agents = sqlx::query_as::<_, RevisionRow>(&sql)
            .bind(company.as_uuid()).bind(run.as_uuid())
            .bind(crate::application::agent::MAX_AGENT_DEFINITION_BYTES as i32)
            .bind(MAX_STEP_ITEMS + 1).fetch_all(self.pool()).await?;
        let agents_truncated = agents.len() as i64 > MAX_STEP_ITEMS;
        agents.truncate(MAX_STEP_ITEMS as usize);
        let mut summaries = Vec::with_capacity(agents.len());
        for agent in agents {
            summaries.push(agent.summary(company)?);
            tokio::task::yield_now().await;
        }
        let mut workflows: Vec<SelectedWorkflowRow> = sqlx::query_as(
            "SELECT selection.workflow_id, selection.version_id FROM run_dependency_manifests AS ownership \
             JOIN agent_manifest_workflows AS selection \
               ON selection.company_id=ownership.company_id AND selection.manifest_id=ownership.manifest_id \
             WHERE ownership.company_id=$1 AND ownership.run_id=$2 \
             ORDER BY selection.workflow_id, selection.version_id LIMIT $3"
        ).bind(company.as_uuid()).bind(run.as_uuid()).bind(MAX_STEP_ITEMS+1)
            .fetch_all(self.pool()).await?;
        let workflows_truncated = workflows.len() as i64 > MAX_STEP_ITEMS;
        workflows.truncate(MAX_STEP_ITEMS as usize);
        Ok(RunDependencies {
            manifest: DependencyManifestId::new(ownership.manifest_id),
            root: RunId::new(ownership.root_run_id),
            agents: summaries,
            agents_truncated,
            workflows: workflows.into_iter().map(|row| WorkflowVersionSelection {
                workflow_id: WorkflowId::new(row.workflow_id),
                version_id: VersionId::new(row.version_id),
            }).collect(),
            workflows_truncated,
        })
    }).await.map_err(|_| invalid_provenance())?
}

pub(super) async fn selected_agent_metadata(
    &self,
    company: CompanyId,
    run: RunId,
    agent: AgentId,
) -> AppResult<SelectedAgentSummary> {
    let sql = format!("{REVISIONS} AND selection.agent_id=$4");
    sqlx::query_as::<_, RevisionRow>(&sql)
        .bind(company.as_uuid())
        .bind(run.as_uuid())
        .bind(crate::application::agent::MAX_AGENT_DEFINITION_BYTES as i32)
        .bind(agent.as_uuid())
        .fetch_optional(self.pool())
        .await?
        .ok_or_else(invalid_provenance)?
        .summary(company)
}

pub(in crate::adapters::persistence::workflow) async fn call_provenance(
    &self,
    company: CompanyId,
    run: RunId,
    actions: &[CallRecordScope],
    children: &[CallRecordScope],
) -> AppResult<CallProvenancePage> {
    if actions.is_empty() && children.is_empty() {
        return Ok(CallProvenancePage::default());
    }
    // Each source is an existing bounded run list; reject misuse of this internal reader.
    if actions.len() > crate::application::workflow::reads::MAX_LISTED as usize
        || children.len() > crate::application::workflow::reads::MAX_LISTED as usize
    {
        return Err(invalid_provenance());
    }
    tokio::time::timeout(Duration::from_secs(5), async {
        let child_ids: Vec<_> = children
            .iter()
            .map(|child| child.record.to_string())
            .collect();
        let action_ids: Vec<_> = actions.iter().map(|action| action.record).collect();
        let executions: Vec<_> = actions
            .iter()
            .chain(children)
            .map(|entry| entry.execution)
            .collect::<BTreeSet<_>>()
            .into_iter()
            .collect();
        let mut rows: Vec<OriginRow> = sqlx::query_as(ORIGINS)
            .bind(company.as_uuid())
            .bind(run.as_uuid())
            .bind(&action_ids)
            .bind(&child_ids)
            .bind(MAX_STEP_ITEMS + 1)
            .bind(&executions)
            .fetch_all(self.pool())
            .await?;
        let truncated = rows.len() as i64 > MAX_STEP_ITEMS;
        rows.truncate(MAX_STEP_ITEMS as usize);
        let origins = rows
            .into_iter()
            .map(|row| {
                let origin: AgentToolOrigin =
                    serde_json::from_value(row.origin).map_err(|_| invalid_provenance())?;
                let kind = match row.kind.as_str() {
                    "action" => CallRecordKind::ActionInvocation,
                    "child" => CallRecordKind::ChildToolCall,
                    _ => return Err(invalid_provenance()),
                };
                Ok(SelectedOrigin {
                    record: row.record,
                    kind,
                    origin,
                })
            })
            .collect::<AppResult<Vec<_>>>()?;
        let definitions = self.call_definitions(company, run, &origins).await?;
        project_calls(
            origins,
            definitions,
            &children
                .iter()
                .map(|child| child.record)
                .collect::<Vec<_>>(),
            truncated,
        )
    })
    .await
    .map_err(|_| invalid_provenance())?
}

async fn call_definitions(
    &self,
    company: CompanyId,
    run: RunId,
    origins: &[SelectedOrigin],
) -> AppResult<HashMap<AgentRevisionId, SelectedAgentSummary>> {
    let revisions: Vec<_> = origins
        .iter()
        .map(|entry| entry.origin.revision.as_uuid())
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect();
    if revisions.is_empty() {
        return Ok(HashMap::new());
    }
    let sql = format!(
        "{REVISIONS} AND selection.revision_id=ANY($4) ORDER BY selection.agent_id LIMIT $5"
    );
    let rows: Vec<RevisionRow> = sqlx::query_as(&sql)
        .bind(company.as_uuid())
        .bind(run.as_uuid())
        .bind(crate::application::agent::MAX_AGENT_DEFINITION_BYTES as i32)
        .bind(&revisions)
        .bind(MAX_STEP_ITEMS + 1)
        .fetch_all(self.pool())
        .await?;
    if rows.len() != revisions.len() {
        return Err(invalid_provenance());
    }
    let mut definitions = HashMap::with_capacity(rows.len());
    for row in rows {
        let summary = row.summary(company)?;
        definitions.insert(summary.revision_id, summary);
        tokio::task::yield_now().await;
    }
    Ok(definitions)
}

fn project_calls(
    origins: Vec<SelectedOrigin>,
    definitions: HashMap<AgentRevisionId, SelectedAgentSummary>,
    children: &[Uuid],
    truncated: bool,
) -> AppResult<CallProvenancePage> {
    let mut identities = BTreeSet::new();
    let items = origins
        .into_iter()
        .map(|entry| {
            if !identities.insert((entry.kind, entry.record)) {
                return Err(invalid_provenance());
            }
            let agent = definitions
                .get(&entry.origin.revision)
                .ok_or_else(invalid_provenance)?;
            if agent.agent_id != entry.origin.agent || agent.manifest != entry.origin.manifest {
                return Err(invalid_provenance());
            }
            let tool = agent
                .bindings
                .iter()
                .find(|tool| tool.binding == entry.origin.binding)
                .ok_or_else(invalid_provenance)?
                .clone();
            Ok(CallProvenance {
                kind: entry.kind,
                record: entry.record,
                origin: entry.origin,
                tool,
            })
        })
        .collect::<AppResult<Vec<_>>>()?;
    if !truncated
        && children
            .iter()
            .any(|child| !identities.contains(&(CallRecordKind::ChildToolCall, *child)))
    {
        return Err(invalid_provenance());
    }
    Ok(CallProvenancePage { items, truncated })
}

